import axiosClient from './axiosClient';

const URL = '/apis/auth';

const authApi = {
  postLogin: (data) => {
    return axiosClient.post(`${URL}/login`, data);
  },
  
  postRegister: (data) => {
    return axiosClient.post(`${URL}/register`, data);
  },

  postLogout: () => {
    return axiosClient.post(`${URL}/logout`);
  },

  postForgotPassword: (email) => {
    return axiosClient.post(`${URL}/forgot-password`, { email });
  },

  postResetPassword: (data) => {
    return axiosClient.post(`${URL}/reset-password`, data);
  },
};

export default authApi;
